-- =============================================================================
-- Migration 011 — word audio in the reading the app teaches.
--
-- Word audio was TTS of the bare character, and edge-tts reads some
-- polyphones alone in another reading: 长 zhǎng (we teach cháng), 教 jiào
-- (jiāo), 差 chā (chà), 数 shǔ (shù), 哪 něi (nǎ), 着 zhāo (zhe), 得 děi (de).
-- Their audio is now committed under public/audio-fixed/words/ (generated by
-- scripts/content/gen-word-audio.py from word-audio-overrides.json).
-- =============================================================================

UPDATE words SET audio_path = '/audio-fixed/words/chang2.mp3' WHERE simplified = '长';
UPDATE words SET audio_path = '/audio-fixed/words/jiao1.mp3'  WHERE simplified = '教';
UPDATE words SET audio_path = '/audio-fixed/words/cha4.mp3'   WHERE simplified = '差';
UPDATE words SET audio_path = '/audio-fixed/words/shu4.mp3'   WHERE simplified = '数';
UPDATE words SET audio_path = '/audio-fixed/words/na3.mp3'    WHERE simplified = '哪';
UPDATE words SET audio_path = '/audio-fixed/words/zhe5.mp3'   WHERE simplified = '着';
UPDATE words SET audio_path = '/audio-fixed/words/de5.mp3'    WHERE simplified = '得';
